## File 1: `src/app/book-a-demo/actions.ts`

```typescript
"use server";

import { z } from "zod";

const DemoRequestSchema = z.object({
  name: z.string().min(2, "Name required"),
  email: z.string().email("Valid email required"),
  studioName: z.string().min(2, "Studio name required"),
  chairs: z.enum(["1", "2-5", "6-10", "11+"]),
  currentTool: z.string().min(1, "Tell us what you're using now"),
  preferredTime: z.enum(["weekday-am", "weekday-pm", "weekend", "flexible"]),
  notes: z.string().max(500).optional(),
});

export interface DemoFormState {
  status: "idle" | "success" | "error";
  message?: string;
  errors?: Record<string, string>;
}

export async function submitDemoRequest(
  _prevState: DemoFormState,
  formData: FormData,
): Promise<DemoFormState> {
  const raw = {
    name: formData.get("name")?.toString() ?? "",
    email: formData.get("email")?.toString() ?? "",
    studioName: formData.get("studioName")?.toString() ?? "",
    chairs: formData.get("chairs")?.toString() ?? "",
    currentTool: formData.get("currentTool")?.toString() ?? "",
    preferredTime: formData.get("preferredTime")?.toString() ?? "",
    notes: formData.get("notes")?.toString() ?? "",
  };

  const parsed = DemoRequestSchema.safeParse(raw);
  if (!parsed.success) {
    const errors: Record<string, string> = {};
    for (const issue of parsed.error.issues) {
      const path = issue.path[0]?.toString();
      if (path && !errors[path]) errors[path] = issue.message;
    }
    return { status: "error", message: "Please fix the errors below", errors };
  }

  // TODO: send to Resend / Boldteq inbox
  console.log("[DEMO REQUEST]", parsed.data);
  await new Promise((r) => setTimeout(r, 600));

  return {
    status: "success",
    message: "We'll be in touch within one business day at the email you gave us.",
  };
}
```

## File 2: `src/components/forms/demo-form.tsx`

`"use client"`. Uses `useActionState` from React 19. All fields strictly typed.

Structure:
- FormField, FormSelect, FormTextarea inline helper components
- Each field: label (12px FONT.sans 600 stoneDark uppercase letterSpacing 0.04em marginBottom 6) + input/select/textarea (full width, padding 11px 14px, FONT.sans 14px ink, border 1px BRAND.border, borderRadius 10, transitions). On focus: borderColor BRAND.rust + boxShadow 0 0 0 3px rgba(200,53,31,0.10). Error 11px crimson marginTop 4. Wrapper marginBottom 16.
- Form: white card, borderRadius 18, padding 32px 28px, SHADOW.card, border 1px BRAND.borderSoft.
- Fields in order: name (text), email (email), studioName (text), [chairs select + preferredTime select in 2-col grid], currentTool (text), notes (textarea rows 3).
- Top-level error banner if `state.status === 'error'`: padding 10px 14px, BRAND.crimsonSoft bg, BRAND.crimson text, borderRadius 8, FONT.sans 13px, marginBottom 16.
- Submit button: full width onyx pill, padding 14px 20px, borderRadius 100, FONT.sans 15/600 bone, ArrowRight 15. Pending state shows "Sending…" with cursor wait + opacity 0.7.
- Footer line below button: 12px FONT.sans stoneFaint center: "We respond within one business day. No calendar tetris."
- Success state replaces entire form: white card, center, sage check circle (56px BRAND.sageWash bg, Check 24 BRAND.sage 2.5 stroke), serif h3 "You're booked." 28px onyx, p 15px stoneDark with state.message.

